function gameKindFromLabel(label){const text=String(label||'').trim().toLowerCase();if(!text)return'';if(/像素少女/.test(text))return'pixelhome';if(/电子宠物/.test(text)||text==='pet')return'pet';if(/像素|拼拼乐|拼豆/.test(text))return'beads';if(/心动审判|情侣问答/.test(text))return'heartquiz';if(/你画我猜|画画/.test(text))return'drawguess';const hit=GAMES.find(x=>x&&(String(x.k).toLowerCase()===text||String(x.n).toLowerCase()===text));return hit&&hit.k||'';}
function latestUserGameInvite(id){return[...msgs(id)].reverse().find(x=>x&&x.type==='gameinvite'&&x.role==='user')||null;}
function roleGameAcceptOrReinvite(id,label){if(gameInviteDecide(id,true))return true;const latest=latestUserGameInvite(id),kind=gameKindFromLabel(label)||(latest&&latest.game)||'';return !!(latest&&latest.status==='declined'&&kind&&roleGameInvite(id,kind));}
function roleGameInvite(id,kind){kind=gameKindFromLabel(kind)||'drawguess';const c=getC(id),g=gameDefinition(kind);if(!c||!g)return false;const recent=[...msgs(id)].reverse().find(x=>x&&x.type==='gameinvite'&&x.game===kind&&x.role==='assistant'&&x.status==='pending');if(recent)return true;const m={role:'assistant',type:'gameinvite',game:kind,gname:g.n,ge:'',status:'pending',from:'ta',id:uid(),time:Date.now()};msgs(id).push(m);notifyIncoming(c,m);save();refreshChatMessages(id);return true;}
function roleGameInviteDecide(id,mid,ok){const c=getC(id),m=msgs(id).find(x=>x&&x.id===mid&&x.type==='gameinvite'&&x.role==='assistant');if(!c||!m||m.status!=='pending')return;m.status=ok?'accepted':'declined';if(ok){c.gamesPlayed=c.gamesPlayed||[];if(c.gamesPlayed.indexOf(m.gname)<0)c.gamesPlayed.push(m.gname);}save();render();if(ok)toast('邀请已接受，可以进入'+(m.gname||'游戏')+'了');}
function enterGameNow(cid,k){const inv=[...msgs(cid)].reverse().find(x=>x.type==='gameinvite'&&x.game===k);if(inv&&inv.status!=='accepted'){toast('要等ta同意了才能进去玩哦');return;}startGame(k,cid);}
function startGame(k,cid){const g=gameDefinition(k);if(!g)return;closeModal();if(k==='tale'||k==='dread')return openApp(k);
  if((k==='pixelhome'||k==='pet')&&!(k==='pet'?typeof openPetGame==='function':typeof openPixelHome==='function'))return northOpenComponent(k,k==='pet'?'电子宠物':'像素少女',()=>k==='pet'?openPetGame():openPixelHome());
  if(k==='pixelhome')return openPixelHome();
  if(k==='pet')return openPetGame();
  if(k==='drawguess')return dgOpenSetup(cid);
  if(k==='beads'&&typeof beadOpenSetup==='function')return beadOpenSetup(cid);
  if(k==='heartquiz')return heartQuizOpenSetup(cid);
  if(k==='soup')return soupCfg(cid);
  if(k==='escape')return escapeCfg(cid);
  if(k==='wordguess')return openGameSpace('wordguess',cid,'我们玩「你说我猜」：轮流出题——一个人描述一个词（不能说出这个词里的任何一个字），另一个人来猜，猜中或想换就继续，自由发挥别老用重复的词。你先出一个词、描述给我猜。','你说我猜');
  if(k==='undercover')return ucConfig(cid);
  openGameSpace(k,cid,g.kick,g.n);}
const MIX_GAME_KEYS=['soup','wordguess','undercover','drama'];
function mgrRooms(){S.me=S.me||{};if(!Array.isArray(S.me.gameRooms))S.me.gameRooms=[];return S.me.gameRooms;}
function mgrGame(k){return GAMES.find(x=>x.k===k)||{k:k,e:'',n:'游戏',kick:'一起玩吧。'};}
function mgrRoom(id){return mgrRooms().find(r=>r.id===id)||null;}
function mgrPlayerKey(kind,id){return kind+':'+id;}
function mgrPfName(id){const f=phoneFriendById(id);return f?pfFriendDisplayName(f):id;}
function mgrLocalTurnKey(r){return r&&r.host?'me':mgrPlayerKey('pf',phoneFriendId());}
function mgrMemberName(r,key){const m=r&&r.members&&r.members[key];if(m&&m.name)return m.name;if(key==='me')return S.me.name||'我';if(key&&key.indexOf('role:')===0){const c=getC(key.slice(5));return c&&(c.remark||c.name)||'角色';}if(key&&key.indexOf('pf:')===0)return mgrPfName(key.slice(3));return '玩家';}
function mgrRoleText(v){if(!v)return'';if(typeof v==='string')return v.slice(0,80);if(typeof v==='object'){const parts=[];['name','title','role','identity','persona','desc','description'].forEach(k=>{if(v[k])parts.push(String(v[k]));});return (parts.join('，')||JSON.stringify(v)).replace(/[{}"]/g,'').slice(0,80);}return String(v).slice(0,80);}
function mgrNormalizeDrama(d){d=d||{};const roles={};Object.keys(d.roles||{}).forEach(k=>roles[k]=mgrRoleText(d.roles[k]));d.scene=mgrRoleText(d.scene||'');d.goal=mgrRoleText(d.goal||'');d.roles=roles;return d;}
function mgrDramaRole(r,key){return mgrRoleText(r&&r.drama&&r.drama.roles&&r.drama.roles[key]);}
function mgrPlayers(r){const a=[{key:'me',name:S.me.name||'我',kind:'me'}];(r.roleIds||[]).forEach(cid=>{const c=getC(cid);a.push({key:mgrPlayerKey('role',cid),name:(c&&(c.remark||c.name))||cid,kind:'role',id:cid});});(r.pfIds||[]).forEach(pid=>a.push({key:mgrPlayerKey('pf',pid),name:mgrPfName(pid),kind:'pf',id:pid}));return a;}
function mgrBuildTurnOrder(r){const roles=(r.roleIds||[]).map(cid=>mgrPlayerKey('role',cid)),pfs=(r.pfIds||[]).map(pid=>mgrPlayerKey('pf',pid));const first=roles.length?[roles[0]]:[];return first.concat(['me'],pfs,roles.slice(1)).filter((x,i,a)=>a.indexOf(x)===i);}
function mgrCurrentTurn(r){const o=r&&r.turnOrder||[];return o.length?o[Math.max(0,Math.min(o.length-1,r.turnIndex||0))]:'';}
function mgrSetTurn(r,key){const o=r.turnOrder||[];const i=o.indexOf(key);r.turnIndex=i>=0?i:0;}
function mgrAdvanceTurn(r){const o=r.turnOrder||[];if(!o.length)return '';r.turnIndex=((r.turnIndex||0)+1)%o.length;return mgrCurrentTurn(r);}
function mgrSystem(r,text,id){return mgrAddRoomMsg(r,{id:id||uid(),kind:'sys',name:'系统',text,time:Date.now()});}
function mgrSeenEvent(r,id){if(!r||!id)return false;r._seenEvents=r._seenEvents||{};if(r._seenEvents[id])return true;r._seenEvents[id]=Date.now();const ks=Object.keys(r._seenEvents);if(ks.length>500)ks.sort((a,b)=>r._seenEvents[a]-r._seenEvents[b]).slice(0,ks.length-500).forEach(k=>delete r._seenEvents[k]);return false;}
function mgrRoomCue(kind){return;}
function openMixedGamePicker(k){const g=mgrGame(k),roles=S.contacts.filter(c=>!c.deleted&&!c.blocked),p=phoneFriendState(),pfs=p.friends||[];
  gameHubModal(`<h3>${esc(g.n)} · 多人房</h3><div class="hint">先做稳定版：可多选角色和小手机真人好友。真人会收到房间邀请卡，全部点准备后房主才能开始。第一版完整支持「即兴小剧场」，其他游戏先接入等待室。</div>
    <div class="field"><label>虚拟角色</label><div class="section">${roles.length?roles.map(c=>`<label class="avline" style="font-weight:400">${av(c.avatar,'sm')}<span style="flex:1">${esc(c.remark||c.name)}</span><span class="sw" data-mgr-role="${c.id}" onclick="this.classList.toggle('on')"></span></label>`).join(''):'<div class="hint" style="padding:8px">暂无可邀请角色</div>'}</div></div>
    <div class="field"><label>小手机真人好友</label><div class="section">${pfs.length?pfs.map(f=>{const id=(''+(f.phone_id||f.id)).toUpperCase();return `<label class="avline" style="font-weight:400">${pfAvatarHTML(f,'sm')}<span style="flex:1">${esc(pfFriendDisplayName(f))}</span><span class="sw" data-mgr-pf="${id}" onclick="this.classList.toggle('on')"></span></label>`;}).join(''):'<div class="hint" style="padding:8px">暂无小手机好友</div>'}</div></div>
    <div class="btns"><button class="btn g" onclick="openGames()">返回</button><button class="btn p" onclick="mgrCreateRoom('${k}')">创建房间</button></div>`);}
function mgrCreateRoom(k){const roles=[...document.querySelectorAll('[data-mgr-role].on')].map(e=>e.getAttribute('data-mgr-role')).filter(Boolean),pfs=[...document.querySelectorAll('[data-mgr-pf].on')].map(e=>e.getAttribute('data-mgr-pf')).filter(Boolean);if(!roles.length&&!pfs.length){toast('至少选一个玩家');return;}
  const g=mgrGame(k),id='mgr_'+uid(),r={id,game:k,title:g.n,hostId:phoneFriendId(),hostName:S.me.name,host:true,status:'lobby',readyMe:false,created:Date.now(),roleIds:roles,pfIds:pfs,roleNames:roles.map(x=>{const c=getC(x);return c&&(c.remark||c.name)||x;}),pfNames:pfs.map(mgrPfName),members:{},msgs:[],busy:false};
  r.members.me={name:S.me.name,kind:'me',ready:false};roles.forEach(cid=>{const c=getC(cid);r.members[mgrPlayerKey('role',cid)]={name:(c&&(c.remark||c.name))||cid,kind:'role',ready:true};});pfs.forEach(pid=>{r.members[mgrPlayerKey('pf',pid)]={name:mgrPfName(pid),kind:'pf',ready:false};});
  mgrRooms().unshift(r);save();closeModal();pfs.forEach(pid=>mgrSendPf(pid,r,{type:'game_room_invite',hostId:r.hostId,hostName:r.hostName,roleNames:r.roleNames,pfNames:r.pfNames,created:r.created}));go('mgroom',{id});}
function mgrSendPf(pid,r,pl){const body=pfPack(Object.assign({roomId:r.id,game:r.game,title:r.title},pl||{}));if(body)sendPhoneFriendBody(pid,body,{silent:true,transport:true});}
function mgrBroadcast(r,pl,exclude){(r.pfIds||[]).forEach(pid=>{if(pid!==exclude)mgrSendPf(pid,r,pl);});}
function mgrStatePayload(r,extra){return Object.assign({type:'game_room_state',eid:uid(),status:r.status,startedAt:r.startedAt||0,drama:r.drama||null,turnOrder:r.turnOrder||[],turnIndex:r.turnIndex||0,members:r.members||{}},extra||{});}
function mgrBroadcastState(r,extra){if(r&&r.host)mgrBroadcast(r,mgrStatePayload(r,extra));}
function mgrApplyState(r,pl){if(!r||!pl)return;if(pl.status)r.status=pl.status;if(pl.startedAt)r.startedAt=pl.startedAt;if(pl.drama)r.drama=mgrNormalizeDrama(pl.drama);if(Array.isArray(pl.turnOrder))r.turnOrder=pl.turnOrder;if(pl.turnIndex!=null)r.turnIndex=+pl.turnIndex||0;if(pl.members&&typeof pl.members==='object')r.members=Object.assign(r.members||{},pl.members);}
function pfHandleGamePayload(m){const pl=pfMsgPayload(m);if(!pl||!pl.type||String(pl.type).indexOf('game_room_')!==0||!pl.roomId)return;const p=phoneFriendState(),me=p.id,from=(''+m.from).toUpperCase(),to=(''+m.to).toUpperCase();let r=mgrRoom(pl.roomId);
  if(pl.type==='game_room_invite'&&from!==me){if(!r){r={id:pl.roomId,game:pl.game,title:pl.title||mgrGame(pl.game).n,hostId:from,hostName:pl.hostName||pfNameById(from)||from,host:false,status:'lobby',readyMe:false,created:pl.created||Date.now(),roleIds:[],pfIds:[from],roleNames:pl.roleNames||[],pfNames:pl.pfNames||[],members:{},msgs:[],busy:false};r.members.host={name:r.hostName,kind:'host',ready:true};r.members.me={name:S.me.name,kind:'me',ready:false};mgrRooms().unshift(r);}return;}
  if(!r)return;
  if(from===me)return;
  if(mgrSeenEvent(r,pl.eid||m.id))return;
  if(pl.type==='game_room_join'){const pid=(''+(pl.playerId||from)).toUpperCase(),key=mgrPlayerKey('pf',pid);r.members[key]=r.members[key]||{kind:'pf',name:pl.playerName||pfNameById(pid)||pid};const was=!!r.members[key].joined;r.members[key].joined=true;if(!was)mgrSystem(r,(r.members[key].name||'玩家')+'进入了房间',pl.eid);if(r.host){mgrBroadcast(r,Object.assign({},pl,{relay:true}),pid);mgrBroadcastState(r);}save();if(cur().p==='mgroom'&&cur().id===r.id)render();return;}
  if(pl.type==='game_room_leave'){const pid=(''+(pl.playerId||from)).toUpperCase(),key=mgrPlayerKey('pf',pid),nm=(r.members&&r.members[key]&&r.members[key].name)||pl.playerName||pfNameById(pid)||'玩家',was=!!(r.members&&r.members[key]&&r.members[key].joined);if(r.members&&r.members[key])r.members[key].joined=false;if(was)mgrSystem(r,nm+'离开了房间',pl.eid);if(r.host){mgrBroadcast(r,Object.assign({},pl,{relay:true}),pid);mgrBroadcastState(r);}save();if(cur().p==='mgroom'&&cur().id===r.id)render();return;}
  if(pl.type==='game_room_ready'){const pid=(''+(pl.playerId||from)).toUpperCase(),key=pid===me?'me':mgrPlayerKey('pf',pid);r.members[key]=r.members[key]||{kind:'pf',name:pl.playerName||pfNameById(pid)||pid};const was=!!r.members[key].ready;r.members[key].ready=true;r.members[key].joined=true;if(!was)mgrSystem(r,(r.members[key].name||'玩家')+'已准备',pl.eid);if(r.host)mgrBroadcastState(r);save();if(cur().p==='mgroom'&&cur().id===r.id)render();return;}
  if(pl.type==='game_room_state'){mgrApplyState(r,pl);save();if(cur().p==='mgroom'&&cur().id===r.id)render();return;}
  if(pl.type==='game_room_start'){r.status='started';r.startedAt=pl.startedAt||Date.now();if(pl.drama)r.drama=mgrNormalizeDrama(pl.drama);if(Array.isArray(pl.turnOrder))r.turnOrder=pl.turnOrder;if(pl.turnIndex!=null)r.turnIndex=+pl.turnIndex||0;mgrApplyState(r,pl);mgrRoomCue('start');save();if(cur().p==='mgroom'&&cur().id===r.id)render();return;}
  if(pl.type==='game_room_chat'){const pid=(''+(pl.playerId||from)).toUpperCase(),mine=pid===me,kind=mine?'me':(pl.playerKind==='me'?'pf':(pl.playerKind||'pf'));const msg={id:pl.eid||uid(),kind,pid,name:pl.playerName||pfNameById(pid)||'真人玩家',text:pl.text||'',time:pl.time||Date.now(),roleName:mgrRoleText(pl.roleName)};if(mgrAddRoomMsg(r,msg)){if(r.host&&from!==me){mgrBroadcast(r,Object.assign({},pl,{relay:true}),from);if(r.status==='started'&&r.game==='drama'){mgrAdvanceTurn(r);mgrBroadcastState(r);setTimeout(()=>mgrRoleTurn(r.id),500);}}save();if(cur().p==='mgroom'&&cur().id===r.id)render();}return;}}
function mgrAddRoomMsg(r,msg){if(!r||!msg||!msg.text&&msg.kind!=='sys')return false;r.msgs=r.msgs||[];if(msg.id&&r.msgs.some(x=>x.id===msg.id))return false;r.msgs.push(msg);if(r.msgs.length>220)r.msgs=r.msgs.slice(-220);return true;}
function openMixedGameRoom(id){let r=mgrRoom(id);if(!r){toast('这个房间还没同步到本机');return;}if(!r.host&&!r._joined){r._joined=true;mgrSystem(r,'你进入了房间');mgrSendPf(r.hostId,r,{type:'game_room_join',eid:uid(),playerId:phoneFriendId(),playerName:S.me.name,time:Date.now()});save();}go('mgroom',{id});phoneFriendMaybeSync(true);}
function mgrReady(id){const r=mgrRoom(id);if(!r||r.status!=='lobby')return;r.readyMe=!r.readyMe;r.members.me=r.members.me||{name:S.me.name,kind:'me'};r.members.me.ready=r.readyMe;mgrSystem(r,r.readyMe?'你已准备':'你取消了准备');save();if(!r.host&&r.readyMe)mgrSendPf(r.hostId,r,{type:'game_room_ready',eid:uid(),playerId:phoneFriendId(),playerName:S.me.name});if(r.host)mgrBroadcastState(r);render();}
function mgrAllReady(r){return !!(r&&r.readyMe&&(r.pfIds||[]).every(pid=>r.members&&r.members[mgrPlayerKey('pf',pid)]&&r.members[mgrPlayerKey('pf',pid)].ready));}
async function mgrBuildDrama(r){const ps=mgrPlayers(r),fallbackRoles=['误入后台的临时演员','掌握线索的旅店前台','嘴硬心软的委托人','偷偷改剧本的人','把气氛弄乱的路人'];let out={scene:'午夜的旧剧院忽然亮灯，所有人收到同一张没有署名的入场券。舞台上只剩一封信：今晚必须演完，门才会打开。',goal:'找到是谁改掉了结局，并把故事演到谢幕。',roles:{}};ps.forEach((p,i)=>out.roles[p.key]=fallbackRoles[i%fallbackRoles.length]);try{const raw=await chatAPI([{role:'system',content:'你是多人即兴小剧场的编剧。生成中文 JSON，不要解释。字段：scene 一段有画面感的开场，goal 一个共同目标，roles 对象，key 必须使用我给的玩家 key。roles 的每个值必须是短字符串，不要写对象。角色要有戏剧冲突但别太长。'},{role:'user',content:'玩家：\n'+ps.map(p=>p.key+' = '+p.name+'（'+p.kind+'）').join('\n')+'\n请生成适合手机聊天扮演的原创小剧场设定。'}],{max:600,aux:true});const m=(''+raw).match(/\{[\s\S]*\}/);if(m){const j=JSON.parse(m[0]);if(j&&j.scene&&j.roles)out={scene:String(j.scene).slice(0,220),goal:String(j.goal||out.goal).slice(0,140),roles:Object.assign(out.roles,j.roles||{})};}}catch(_){}return mgrNormalizeDrama(out);}
async function mgrStart(id){const r=mgrRoom(id);if(!r||!r.host||r._starting)return;if(!mgrAllReady(r)){toast('要等所有真人好友都准备好');return;}r._starting=true;render();r.status='started';r.startedAt=Date.now();r.turnOrder=mgrBuildTurnOrder(r);r.turnIndex=0;r.drama=r.game==='drama'?await mgrBuildDrama(r):{scene:'房间已开始。',goal:'按规则完成这一局。',roles:{}};delete r._starting;if(r.game!=='drama')mgrSystem(r,'房间已开始，这个游戏的多人规则后续继续补全。');save();mgrBroadcast(r,Object.assign(mgrStatePayload(r),{type:'game_room_start',eid:uid()}));mgrRoomCue('start');render();if(r.game==='drama')setTimeout(()=>mgrRoleTurn(id),500);}
function mgrSend(id){const r=mgrRoom(id);if(!r||r.status!=='started')return;const myKey=mgrLocalTurnKey(r),ta=$('#mgr_in'),text=(ta&&ta.value||'').trim();if(!text)return;if(ta)ta.value='';const msg={id:uid(),kind:'me',pid:phoneFriendId(),name:S.me.name,text,time:Date.now(),roleName:mgrDramaRole(r,myKey)};mgrAddRoomMsg(r,msg);save();if(r.host){mgrBroadcast(r,{type:'game_room_chat',eid:msg.id,playerId:msg.pid,playerKind:'me',playerName:msg.name,roleName:msg.roleName,text:msg.text,time:msg.time});if(r.game==='drama'){mgrAdvanceTurn(r);mgrBroadcastState(r);setTimeout(()=>mgrRoleTurn(id),500);}}else mgrSendPf(r.hostId,r,{type:'game_room_chat',eid:msg.id,playerId:msg.pid,playerKind:'pf',playerName:msg.name,roleName:msg.roleName,text:msg.text,time:msg.time});render();}
async function mgrRoleTurn(id){const r=mgrRoom(id);if(!r||!r.host||r.busy||r.status!=='started'||r.game!=='drama')return;const key=mgrCurrentTurn(r);if(!key||key.indexOf('role:')!==0)return;const cid=key.slice(5),c=getC(cid);if(!c){mgrAdvanceTurn(r);mgrBroadcastState(r);return;}r.busy=true;save();render();const roleName=mgrDramaRole(r,key),hist=gameContextRows(r.msgs||[]).map(m=>(m.kind==='sys'?'系统':((m.roleName?m.roleName+'｜':'')+m.name))+'：'+m.text).join('\n');
  try{const sys=buildSystem(c,{worldbookScope:'games'})+'\n\n# 多人游戏房：即兴小剧场\n这是独立游戏房，不是微信日常聊天。你正在扮演系统分配给你的剧场身份：「'+roleName+'」。\n剧情开场：'+((r.drama&&r.drama.scene)||'')+'\n共同目标：'+((r.drama&&r.drama.goal)||'')+'\n真人好友是真人玩家，只能由他们自己发言；你绝对不要替真人说话、不要编他们的动作或台词。\n现在轮到你发言：只说你这个角色的一小段台词或动作，1到2句，有画面感，推动剧情，但别写旁白标题。';const out=cleanReply(await chatAPI([{role:'system',content:sys},{role:'user',content:'房间最近记录：\n'+hist+'\n接住上一句，轮到你。'}],{max:180,aux:c.model==='aux'}));if(out){const msg={id:uid(),kind:'role',pid:cid,name:c.remark||c.name,roleName,text:out,time:Date.now()};mgrAddRoomMsg(r,msg);mgrBroadcast(r,{type:'game_room_chat',eid:msg.id,playerId:cid,playerKind:'role',playerName:msg.name,roleName:msg.roleName,text:msg.text,time:msg.time});}}catch(e){mgrSystem(r,(c.remark||c.name)+'卡了一下，舞台灯光闪了闪。');}
  r.busy=false;mgrAdvanceTurn(r);mgrBroadcastState(r);save();if(cur().p==='mgroom'&&cur().id===id)render();setTimeout(()=>mgrRoleTurn(id),650);}
function mgrQuit(){const r=cur().p==='mgroom'?mgrRoom(cur().id):null;if(r){(r.roleIds||[]).forEach(cid=>gameSetHandoff(cid,r.title||mgrGame(r.game).n,r.msgs||[]));if(!r.host&&r._joined){mgrSendPf(r.hostId,r,{type:'game_room_leave',eid:uid(),playerId:phoneFriendId(),playerName:S.me.name,time:Date.now()});r._joined=false;save();}}back();}
