async function clReplayRevoice(id,cs){if(_callReplayRevoiceBusy){toast('正在重新配音，请稍等');return;}const c=getC(id),rows=callReplayPickRows(id,cs);if(!c||!rows.length)return;if(!ttsApiOn(c)){toast('请先在角色语音设置中配置并开启外置语音');return;}const lang=ttsContentLang(c),targets=rows.filter(x=>x.role==='assistant'&&!x.action&&pickSpoken(x.text,lang));if(!targets.length){toast('请选择TA说话的时间点');return;}let points=0;targets.forEach(x=>{const t=ttsPerformanceText(pickSpoken(x.text,lang),c,ttsCfg(c),{cue:x.cue,interjection:x.interjection});points+=typeof aiTtsPointCost==='function'?aiTtsPointCost([...t].length):Math.max(1,Math.ceil([...t].length/50));});const note=ttsUseRelay(c)?'预计扣除约 '+points+' 点；每句成功才扣，失败不扣。':'使用这个角色选择的外置语音路线，不扣内置AI点数。';if(!await uiConfirm('将重新生成所选的 '+targets.length+' 个时间点声音。\n'+note+'\n已有声音仅在新声音成功保存后替换；失败会保留原声音。'))return;_callReplayRevoiceBusy=true;closeModal();audioUnlock();toast('正在按原台词和情绪重新生成声音…');let ok=0,fail=0;for(const row of targets){const m=msgs(id).find(x=>String(x.id)===String(row.id));if(!m)continue;let ab=null;try{const spoken=pickSpoken(m.content,lang);ab=await ttsArr(spoken,c,{cue:row.cue,interjection:row.interjection});const buf=await decodeBuf(ab);if(buf){const stored=await callReplayReplaceAudio(m,ab,buf.duration);if(stored){m._callVoiceCue=row.cue||'';m._callVoiceInterjection=row.interjection;ok++;}else{if(ab)await ttsRefundAudio(ab,'call-revoice-store-failed');fail++;}}else{if(ab)await ttsRefundAudio(ab,'call-revoice-decode-failed');fail++;}}catch(_){if(ab)await ttsRefundAudio(ab,'call-revoice-exception');fail++;}}_callReplayRevoiceBusy=false;save();if(typeof aiAccountRefresh==='function')setTimeout(()=>aiAccountRefresh(true,true),500);const ids=new Set(rows.map(x=>String(x.id))),fresh=callReplayRows(id,cs).filter(x=>ids.has(String(x.id)));toast(ok?'已重新生成 '+ok+' 个时间点'+(fail?'，'+fail+'个失败未替换':''):'重新生成失败，原声音已保留');if(ok)clReplayStartRows(id,cs,fresh);}
function callReplayPlayFull(buf){ensureAudio();return new Promise(res=>{if(!_audio||!buf){res();return;}try{if(_audio.state==='suspended'||_audio.state==='interrupted')_audio.resume();stopBufSource('replaced-by-call-replay');const src=_audio.createBufferSource(),gain=_audio.createGain();src.buffer=buf;gain.gain.value=volMul();src.connect(gain);gain.connect(_audio.destination);let done=false;const end=()=>{if(done)return;done=true;res();};src.onended=end;src.start();_curSrc=src;setTimeout(end,buf.duration*1000+1200);}catch(_){res();}});}
