async function clReplayStart(id,cs){const rows=callReplayPickRows(id,cs);if(!rows.length)return;if(!rows.some(x=>x.audio)){toast('这段没有保存声音，不能有声回放');return;}closeModal();_callReplay={id,cs,rows,index:0,sub:null,done:false,token:uid()};const token=_callReplay.token;renderCall();for(let i=0;i<rows.length;i++){if(!_callReplay||_callReplay.token!==token)return;_callReplay.index=i;_callReplay.sub={who:rows[i].role==='user'?'me':'them',text:rows[i].text+(rows[i].trans?'\n'+rows[i].trans:'')};updateCallReplaySub();await callReplayPlayRow(rows[i]);await sleep(220);}if(_callReplay&&_callReplay.token===token){_callReplay.done=true;_callReplay.sub=null;renderCall();}}
